import { randomBytes } from "node:crypto";

import { joinStorageKey, parseStorageKey } from "@/lib/file-storage/keys";

/*
 * Recorded Lectures storage layout (RL-1), relative to FILE_STORAGE_ROOT:
 *
 *   Teachers/{teacherId}/Lectures/{lectureId}/RecordedLectures/{recordingId}/{32 hex}.mp4
 *   System/TemporaryUploads/{uploadId}.part                 (the upload being assembled)
 *   System/TemporaryUploads/{uploadId}.{leaseToken}.chunk   (one in-flight chunk)
 *
 * Every id is a lowercase UUID generated by the application and every file
 * name is generated here; nothing from a request (file name, path) is ever
 * part of a key. The database stores these RELATIVE keys, never absolute
 * paths, and a stored key is never recomputed (a lecture's teacher could
 * change; the key records where the file was written).
 */

export const TEACHERS_DIRECTORY = "Teachers";
export const TEMPORARY_UPLOADS_DIRECTORY = "System/TemporaryUploads";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const STORED_NAME = /^[0-9a-f]{32}\.mp4$/;
const LEASE_TOKEN = /^[0-9a-f]{64}$/;

export function isRecordedLectureId(value: unknown): value is string {
  return typeof value === "string" && UUID.test(value);
}

export function isLeaseToken(value: unknown): value is string {
  return typeof value === "string" && LEASE_TOKEN.test(value);
}

function requireId(value: unknown): string {
  if (!isRecordedLectureId(value)) throw new Error("Invalid recorded lecture id.");
  return value;
}

/** A new stored file name: 128 random bits, hex, ".mp4". */
export function generateRecordingFileName(): string {
  return `${randomBytes(16).toString("hex")}.mp4`;
}

/** A new chunk lease token: 256 random bits, hex. Never reused. */
export function generateLeaseToken(): string {
  return randomBytes(32).toString("hex");
}

export function recordingDirectoryKey(input: { teacherId: string; lectureId: string; recordingId: string }): string {
  return joinStorageKey(
    TEACHERS_DIRECTORY,
    requireId(input.teacherId),
    "Lectures",
    requireId(input.lectureId),
    "RecordedLectures",
    requireId(input.recordingId)
  );
}

export function recordingFileKey(input: { teacherId: string; lectureId: string; recordingId: string; storedName: string }): string {
  if (!STORED_NAME.test(input.storedName)) throw new Error("Invalid stored recording name.");
  return `${recordingDirectoryKey(input)}/${input.storedName}`;
}

export function uploadTempKey(uploadId: string): string {
  return joinStorageKey(TEMPORARY_UPLOADS_DIRECTORY, `${requireId(uploadId)}.part`);
}

export function chunkScratchKey(uploadId: string, leaseToken: string): string {
  if (!isLeaseToken(leaseToken)) throw new Error("Invalid lease token.");
  return joinStorageKey(TEMPORARY_UPLOADS_DIRECTORY, `${requireId(uploadId)}.${leaseToken}.chunk`);
}

export type RecordedLectureKeyKind =
  | { kind: "recording"; teacherId: string; lectureId: string; recordingId: string; storedName: string }
  | { kind: "temp"; uploadId: string }
  | { kind: "scratch"; uploadId: string; leaseToken: string };

/** Classifies a key produced by this module; null for anything else (never deleted automatically). */
export function parseRecordedLectureKey(key: string): RecordedLectureKeyKind | null {
  let segments: string[];
  try {
    segments = parseStorageKey(key);
  } catch {
    return null;
  }

  if (
    segments.length === 7 &&
    segments[0] === TEACHERS_DIRECTORY &&
    UUID.test(segments[1]) &&
    segments[2] === "Lectures" &&
    UUID.test(segments[3]) &&
    segments[4] === "RecordedLectures" &&
    UUID.test(segments[5]) &&
    STORED_NAME.test(segments[6])
  ) {
    return { kind: "recording", teacherId: segments[1], lectureId: segments[3], recordingId: segments[5], storedName: segments[6] };
  }

  if (segments.length === 3 && segments[0] === "System" && segments[1] === "TemporaryUploads") {
    const temp = /^([0-9a-f-]{36})\.part$/.exec(segments[2]);
    if (temp && UUID.test(temp[1])) return { kind: "temp", uploadId: temp[1] };
    const scratch = /^([0-9a-f-]{36})\.([0-9a-f]{64})\.chunk$/.exec(segments[2]);
    if (scratch && UUID.test(scratch[1])) return { kind: "scratch", uploadId: scratch[1], leaseToken: scratch[2] };
  }

  return null;
}
